import sys
import re


def is_number(cell):
    if not cell:
        return False
    if cell[0] == '-' and cell[1:].isdigit():
        return True
    if '.' in cell:
        parts = cell.split('.')
        if len(parts) == 2 and parts[1].isdigit():
            return True
    return cell.isdigit()


def main():
    rows = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        cells = line.split("|")
        cells = [cell.strip() for cell in cells]
        rows.append(cells)

    if not rows:
        return

    header = rows[0]
    data_rows = rows[1:]

    # Calculate widths
    widths = [max(len(cell) for cell in column) for column in zip(*rows)]

    def fmt(row):
        cells = []
        for i, cell in enumerate(row):
            width = widths[i]
            if is_number(cell):
                cells.append(cell.rjust(width))
            else:
                cells.append(cell.ljust(width))
        return " | ".join(cells)

    print(fmt(header))
    print("-+-".join("-" * w for w in widths))
    for row in data_rows:
        print(fmt(row))


if __name__ == "__main__":
    main()
